class Solution:
    def minCost(self, n, edges, k):
        ws = sorted(set(w for _, _, w in edges))
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]; x = parent[x]
            return x
        def feasible(x):
            for i in range(n): parent[i] = i
            for u, v, w in edges:
                if w <= x:
                    ru, rv = find(u), find(v)
                    if ru != rv: parent[ru] = rv
            return len({find(i) for i in range(n)}) <= k
        lo, hi = 0, len(ws)  # candidates: 0 and ws
        cand = [0] + ws
        lo, hi = 0, len(cand) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(cand[mid]): hi = mid
            else: lo = mid + 1
        return cand[lo]

