class Solution {
public:
    int minCost(int n, vector<vector<int>>& edges, int k) {
        vector<int> ws;
        for (auto& e : edges) ws.push_back(e[2]);
        sort(ws.begin(), ws.end()); ws.erase(unique(ws.begin(), ws.end()), ws.end());
        vector<int> cand; cand.push_back(0); for (int w : ws) cand.push_back(w);
        vector<int> parent(n);
        function<int(int)> find = [&](int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
        auto feasible = [&](long long x) {
            iota(parent.begin(), parent.end(), 0);
            for (auto& e : edges) if (e[2] <= x) { int ru = find(e[0]), rv = find(e[1]); if (ru != rv) parent[ru] = rv; }
            unordered_set<int> roots; for (int i = 0; i < n; i++) roots.insert(find(i));
            return (int)roots.size() <= k;
        };
        int lo = 0, hi = (int)cand.size() - 1;
        while (lo < hi) { int mid = (lo + hi) / 2; if (feasible(cand[mid])) hi = mid; else lo = mid + 1; }
        return cand[lo];
    }
};

