class Solution {
    public int minCost(int n, int[][] edges, int k) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] e : edges) set.add(e[2]);
        List<Long> cand = new ArrayList<>(); cand.add(0L); for (int w : set) cand.add((long) w);
        int[] parent = new int[n];
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            public int applyAsInt(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
        };
        class F { boolean feas(long x) {
            for (int i = 0; i < n; i++) parent[i] = i;
            for (int[] e : edges) if (e[2] <= x) { int ru = find.applyAsInt(e[0]), rv = find.applyAsInt(e[1]); if (ru != rv) parent[ru] = rv; }
            Set<Integer> roots = new HashSet<>(); for (int i = 0; i < n; i++) roots.add(find.applyAsInt(i));
            return roots.size() <= k;
        }}
        F f = new F();
        int lo = 0, hi = cand.size() - 1;
        while (lo < hi) { int mid = (lo + hi) / 2; if (f.feas(cand.get(mid))) hi = mid; else lo = mid + 1; }
        return cand.get(lo).intValue();
    }
}

