var minCost = function(n, edges, k) {
    const ws = [...new Set(edges.map(e => e[2]))].sort((a, b) => a - b);
    const cand = [0, ...ws];
    const parent = new Array(n);
    const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
    const feasible = (x) => {
        for (let i = 0; i < n; i++) parent[i] = i;
        for (const [u, v, w] of edges) if (w <= x) { const ru = find(u), rv = find(v); if (ru !== rv) parent[ru] = rv; }
        const roots = new Set(); for (let i = 0; i < n; i++) roots.add(find(i));
        return roots.size <= k;
    };
    let lo = 0, hi = cand.length - 1;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (feasible(cand[mid])) hi = mid; else lo = mid + 1; }
    return cand[lo];
};
